-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 13: Normalização: formas normais superiores — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('abd2dd33-f1a6-525a-8476-60727a659562', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Uma dependência multivalorada trata principalmente de:', '["Permissões de usuário.","Ordenação física das linhas.","Criptografia de colunas.","Quantidade de índices.","Independência entre conjuntos de valores associados a um determinante."]'::jsonb, 4, 'DMVs capturam combinações independentes que DFs não descrevem completamente.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('397dfb61-3e56-5300-b2a5-a933ffb4fca8', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Um aluno possui idiomas e esportes independentes entre si. Em R(Aluno,Idioma,Esporte), essa independência sugere:', '["Aluno →→ Idioma e Aluno →→ Esporte.","Esporte → Aluno obrigatoriamente.","Ausência de qualquer dependência.","Idioma → Aluno obrigatoriamente.","Aluno → Idioma e Aluno → Esporte obrigatoriamente."]'::jsonb, 0, 'Vários valores independentes por aluno indicam DMVs, não necessariamente DFs.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('25e53f9d-e8ac-5515-8371-f870a8332550', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Para um aluno com dois idiomas e três esportes independentes, quantas combinações completas aparecem em R?', '["5.","3.","2.","6.","1."]'::jsonb, 3, 'A independência requer o produto das duas coleções para aquele determinante.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f65ade8d-cf19-5680-84a7-c17c27616bb7', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Médio', 'Qual decomposição remove a repetição causada por idiomas e esportes independentes?', '["Uma relação por combinação completa.","AlunoIdioma e AlunoEsporte.","Aluno apenas.","Três relações sem o identificador do aluno.","IdiomaEsporte apenas."]'::jsonb, 1, 'As projeções preservam separadamente cada conjunto de fatos independentes.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('14a4a761-0191-5b77-aca7-83434f341abf', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Médio', 'A 4FN exige que toda DMV não trivial tenha como determinante:', '["Uma coluna fisicamente ordenada.","Uma superchave.","Um atributo não primo.","Uma chave estrangeira necessariamente.","Um atributo textual."]'::jsonb, 1, 'Essa condição evita redundância multivalorada não justificada por chaves.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('033a6194-a0e5-51a3-8df9-d74e196a75ab', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'Toda dependência funcional X → Y implica uma DMV X →→ Y?', '["Somente se X for vazio.","Não, DFs e DMVs são incompatíveis.","Somente se Y for numérico.","Sim.","Somente em bancos distribuídos."]'::jsonb, 3, 'DMVs generalizam DFs; o sentido inverso não vale em geral.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f54431c0-e88f-59c8-839f-a7295f285e13', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Uma DMV X →→ Y implica necessariamente X → Y?', '["Não; pode haver vários valores de Y para o mesmo X.","Sim, se o banco for relacional.","Sim, se houver mais de uma linha.","Não, porque DMVs não admitem determinantes.","Sim, por definição."]'::jsonb, 0, 'A DF exige um único valor dependente por determinante; a DMV não.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('82837954-24c3-55dd-8f23-b9d1d2e7e70d', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Uma relvar em FNBC pode ainda conter redundância por quê?', '["FNBC ignora todas as DFs.","A FNBC elimina os tipos.","FNBC exige duplicação de todas as tuplas.","Toda chave candidata viola uma DMV.","Podem existir DMVs não triviais com determinante que não seja superchave."]'::jsonb, 4, 'FNBC resolve condições sobre DFs, mas não todas as dependências multivaloradas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f9cc4c72-8653-50e3-92ed-cd14f3c88aae', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma dependência de junção declara que uma relação é igual:', '["À primeira linha de cada projeção.","À união arbitrária de quaisquer tabelas.","À junção de determinadas projeções suas.","A uma lista ordenada de atributos.","A um produto físico de arquivos."]'::jsonb, 2, 'A DJ expressa a reconstrução sem perdas por um conjunto de projeções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4a9c4c25-2860-5ee9-864a-e21bc0b143c6', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma DJ pode envolver mais de duas projeções?', '["Somente em arquivos não relacionais.","Não, pois junções são sempre unárias.","Sim.","Não, toda DJ é binária.","Somente se não houver chaves."]'::jsonb, 2, 'Certas redundâncias só são reveladas por decomposições em três ou mais projeções.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f0827a09-f3ee-5f1f-acb7-12ac3c793c95', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Qual forma normal é também chamada forma normal de projeção-junção?', '["FNBC.","1FN.","5FN.","3FN.","2FN."]'::jsonb, 2, 'A 5FN trata das dependências de junção não triviais.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8382f474-262d-50c6-8bda-a771bd691fe2', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'Na 5FN, as dependências de junção não triviais devem ser justificadas por:', '["Número de discos.","Ordem dos atributos.","Endereços físicos.","Senhas dos usuários.","Chaves candidatas."]'::jsonb, 4, 'O critério exclui redundância de junção que não decorra das chaves.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('832b64aa-5ec9-5748-a730-a8d614707634', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Toda relvar em 5FN está em 4FN?', '["Sim.","Não, porque a 5FN dispensa DMVs.","Somente se estiver vazia.","Não, são formas independentes.","Somente se tiver uma chave simples."]'::jsonb, 0, 'A hierarquia de formas normais exige também as condições anteriores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('36d3d42e-b1a5-5608-bf7f-70f1c6ff4929', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'A 4FN garante, por si só, a ausência de toda redundância baseada em DJs de maior ordem?', '["Não, porque 4FN exige duplicatas.","Sim, se houver índices.","Sim, desde que haja três atributos.","Não; essa motivação leva à 5FN.","Sim, toda DJ é uma DF."]'::jsonb, 3, 'DMVs não esgotam as dependências de junção possíveis.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.3, páginas 637–643 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('38d48861-557f-5471-bb63-8cdbfc1dbfbc', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'Ao decompor uma relação durante a normalização, qual propriedade deve ser preservada?', '["Número original de colunas em cada projeção.","Reconstrução sem perdas.","Ordem de inserção.","Quantidade de páginas do índice.","Nome físico do arquivo."]'::jsonb, 1, 'Dividir tabelas sem preservar informação não constitui uma decomposição adequada.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.4, páginas 644–647 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1eacfa51-7e02-553c-be8b-8c85071b18d5', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Date recomenda assumir que desnormalizar é sempre necessário para desempenho?', '["Sim, toda junção torna o banco inviável.","Sim, a 5FN impede índices.","Não; desempenho e projeto lógico devem ser analisados separadamente.","Sim, qualquer duplicação é benéfica.","Não, porque desempenho não importa."]'::jsonb, 2, 'Não se deve abandonar um bom projeto lógico por uma regra geral de desempenho sem análise.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.5, páginas 648–651 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8a86e63a-3db1-55cf-80ab-337d611c7d26', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Médio', 'Materializar um resultado para acelerar consultas deve exigir atenção a:', '["Proibição de qualquer redundância controlada.","Apenas escolha da cor da interface.","Remoção de todas as chaves.","Atualização e consistência da informação derivada.","Dispensa de renovação."]'::jsonb, 3, 'Uma representação redundante mantida por razões físicas precisa de controle.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.5, páginas 648–651 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0d8ec0fb-3758-548f-8cad-7dca1a75ec4a', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Médio', 'O princípio de projeto ortogonal busca evitar principalmente:', '["Toda junção em consultas.","Qualquer relacionamento entre entidades.","Toda referência entre tabelas.","Todos os tipos definidos pelo usuário.","Representações redundantes e sobrepostas do mesmo fato em relvars diferentes."]'::jsonb, 4, 'O princípio complementa a preocupação com redundância entre relvars distintas.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.6, páginas 652–656 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dc5c455b-5e69-599b-9839-b3d75864dfb6', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Difícil', 'Se idiomas e esportes não forem independentes, decompor somente em AlunoIdioma e AlunoEsporte pode:', '["Criar combinações não autorizadas ao recompor por junção.","Produzir uma única tupla por aluno.","Preservar obrigatoriamente a associação original.","Garantir sempre a mesma relação.","Eliminar automaticamente todas as restrições."]'::jsonb, 0, 'A decomposição depende da validade da DMV, não apenas dos nomes dos atributos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.2, páginas 631–636 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c3f24048-848e-5fd6-b93a-2ccd1432dcdf', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Por que inferir dependências somente a partir da amostra atual é arriscado?', '["Porque amostras nunca contêm dados.","Ela pode omitir combinações válidas ou violações possíveis em outros estados.","Porque toda amostra determina a 5FN.","Porque a normalização independe da semântica.","Porque dependências são físicas."]'::jsonb, 1, 'Dependências são regras dos estados admissíveis, não coincidências de uma fotografia dos dados.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 13, seção 13.4, páginas 644–647 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
